/**
 * ErgoScore result dashboard.
 *
 * Responsible only for visualizing the structured result
 * generated by the Flask analysis pipeline.
 */

document.addEventListener("DOMContentLoaded", () => {

    const dataElement =
        document.getElementById("result-data");

    if (!dataElement) {
        return;
    }


    let resultData;

    try {

        resultData =
            JSON.parse(dataElement.textContent);

    } catch (error) {

        console.error(
            "Unable to parse ErgoScore result data:",
            error
        );

        return;
    }


    if (typeof Chart === "undefined") {

        console.error(
            "Chart.js was not loaded."
        );

        return;
    }


    renderRiskDistributionChart(
        resultData.risk_distribution
    );


    renderScoreTimelineChart(
        resultData.timeline
    );

});


/* =========================================================
   RISK DISTRIBUTION
========================================================= */

function renderRiskDistributionChart(distribution) {

    const canvas =
        document.getElementById(
            "risk-distribution-chart"
        );

    if (!canvas || !distribution) {
        return;
    }


    const low =
        Number(distribution.low) || 0;

    const medium =
        Number(distribution.medium) || 0;

    const high =
        Number(distribution.high) || 0;


    new Chart(canvas, {

        type: "doughnut",

        data: {

            labels: [
                "Low",
                "Medium",
                "High"
            ],

            datasets: [

                {
                    data: [
                        low,
                        medium,
                        high
                    ],

                    backgroundColor: [
                        "#16865a",
                        "#c57900",
                        "#c32f3d"
                    ],

                    borderColor: "#ffffff",

                    borderWidth: 3,

                    hoverOffset: 6
                }

            ]

        },

        options: {

            responsive: true,

            maintainAspectRatio: false,

            cutout: "68%",

            plugins: {

                legend: {

                    position: "bottom",

                    labels: {

                        usePointStyle: true,

                        pointStyle: "circle",

                        padding: 20,

                        font: {
                            size: 12
                        }
                    }
                },

                tooltip: {

                    callbacks: {

                        label: function(context) {

                            return (
                                `${context.label}: ` +
                                `${context.parsed}%`
                            );

                        }

                    }

                }

            }

        }

    });

}


/* =========================================================
   SCORE TIMELINE
========================================================= */

function renderScoreTimelineChart(timeline) {

    const canvas =
        document.getElementById(
            "score-timeline-chart"
        );

    if (!canvas) {
        return;
    }


    if (!Array.isArray(timeline) ||
        timeline.length === 0) {

        showEmptyTimeline(canvas);

        return;
    }


    /*
     * The pipeline normally provides:
     *
     * {
     *     time: 0,
     *     score: 5
     * }
     *
     * We also support timestamp / reba_score so
     * minor backend naming differences don't break
     * the dashboard.
     */

    const labels = [];

    const scores = [];


    timeline.forEach((point, index) => {

        if (!point) {
            return;
        }


        let time;


        if (point.time !== undefined) {

            time =
                Number(point.time);

        } else if (
            point.timestamp !== undefined
        ) {

            time =
                parseFloat(point.timestamp);

        } else {

            time =
                index;

        }


        let score;


        if (point.score !== undefined) {

            score =
                Number(point.score);

        } else if (
            point.reba_score !== undefined
        ) {

            score =
                Number(point.reba_score);

        } else if (
            point.reba !== undefined
        ) {

            if (
                typeof point.reba === "object" &&
                point.reba.reba_score !== undefined
            ) {

                score =
                    Number(
                        point.reba.reba_score
                    );

            } else {

                score =
                    Number(point.reba);

            }

        } else {

            return;

        }


        if (!Number.isFinite(score)) {
            return;
        }


        if (!Number.isFinite(time)) {
            time = index;
        }


        labels.push(
            `${time.toFixed(2)}s`
        );

        scores.push(score);

    });


    if (scores.length === 0) {

        showEmptyTimeline(canvas);

        return;
    }


    new Chart(canvas, {

        type: "line",

        data: {

            labels: labels,

            datasets: [

                {

                    label: "REBA Score",

                    data: scores,

                    borderColor: "#3156d3",

                    backgroundColor:
                        "rgba(49, 86, 211, 0.08)",

                    borderWidth: 2.5,

                    fill: true,

                    tension: 0.25,

                    pointRadius:
                        scores.length > 80
                            ? 0
                            : 3,

                    pointHoverRadius: 5,

                    pointBackgroundColor:
                        "#3156d3"
                }

            ]

        },

        options: {

            responsive: true,

            maintainAspectRatio: false,

            interaction: {

                intersect: false,

                mode: "index"

            },

            scales: {

                y: {

                    beginAtZero: true,

                    min: 0,

                    max: 15,

                    ticks: {

                        stepSize: 1
                    },

                    title: {

                        display: true,

                        text: "REBA Score"
                    },

                    grid: {

                        color:
                            "rgba(16, 27, 63, 0.08)"
                    }

                },

                x: {

                    title: {

                        display: true,

                        text: "Time"
                    },

                    grid: {
                        display: false
                    },

                    ticks: {

                        maxTicksLimit: 8
                    }

                }

            },

            plugins: {

                legend: {
                    display: false
                },

                tooltip: {

                    callbacks: {

                        title: function(context) {

                            return (
                                "Time: " +
                                context[0].label
                            );

                        },

                        label: function(context) {

                            return (
                                "REBA Score: " +
                                context.parsed.y
                            );

                        }

                    }

                }

            }

        }

    });

}


/* =========================================================
   EMPTY TIMELINE
========================================================= */

function showEmptyTimeline(canvas) {

    const parent =
        canvas.parentElement;

    parent.innerHTML = `
        <div class="chart-empty">
            <div class="chart-empty-icon">—</div>
            <strong>No timeline data available</strong>
            <span>
                Temporal score data was not returned
                by the analysis pipeline.
            </span>
        </div>
    `;

}